tool.command:
## Sleep to simulate a slow conversion - allows testing race conditions
sleep 2 &&
awk 'BEGIN{FS="\t"; OFS="\t"} !/^#/ && NF>=3 {
    chrom=$1; start=$2; end=$3;
    name=(NF>=4 ? $4 : ".");
    score=(NF>=5 ? $5 : "0");
    strand=(NF>=6 ? $6 : ".");
    print chrom, start, end, name, score, strand
}' '$input1' > '$output1'
